option.value:
.error-boundary {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.error-container {
  background: white;
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
  max-width: 500px;
  text-align: center;
  margin: 20px;
}

.error-container h1 {
  font-size: 2.5rem;
  color: #d33;
  margin: 0 0 20px 0;
  line-height: 1;
}

.error-message {
  font-size: 1.1rem;
  color: #333;
  margin: 20px 0;
  line-height: 1.6;
  word-break: break-word;
}

.error-details {
  font-size: 0.9rem;
  color: #666;
  margin: 15px 0;
  padding: 10px;
  background: #f5f5f5;
  border-left: 4px solid #d33;
  border-radius: 4px;
  text-align: left;
  word-break: break-all;
}

.error-button {
  background: #667eea;
  color: white;
  border: none;
  padding: 12px 30px;
  font-size: 1rem;
  border-radius: 6px;
  cursor: pointer;
  margin-top: 20px;
  transition: all 0.3s ease;
}

.error-button:hover {
  background: #764ba2;
  transform: translateY(-2px);
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

.error-button:active {
  transform: translateY(0);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

import { useEffect, useState } from 'react';
import Swal from 'sweetalert2';
import './index.css';

export function ErrorBoundary({ children }) {
  const [error, setError] = useState(null);

  useEffect(() => {
    const handleError = (event) => {
      console.error('Erro não tratado:', event.error);

      setError({
        message: event.error?.message || event.message || 'Erro desconhecido',
        stack: event.error?.stack,
        source: event.filename,
        lineno: event.lineno
      });

      Swal.fire({
        icon: "error",
        title: "Erro não tratado",
        text: "Ocorreu um erro inesperado. A página será recarregada.",
        confirmButtonText: "OK",
        allowOutsideClick: false,
        allowEscapeKey: false
      }).then(() => {
        window.location.reload();
      });
    };

    const handleUnhandledRejection = (event) => {
      console.error('Promise rejeitada não tratada:', event.reason);

      setError({
        message: event.reason?.message || 'Promise rejeitada não tratada',
        reason: event.reason
      });

      Swal.fire({
        icon: "error",
        title: "Erro não tratado",
        text: "Ocorreu um erro inesperado. A página será recarregada.",
        confirmButtonText: "OK",
        allowOutsideClick: false,
        allowEscapeKey: false
      }).then(() => {
        window.location.reload();
      });
    };

    window.addEventListener('error', handleError);
    window.addEventListener('unhandledrejection', handleUnhandledRejection);

    return () => {
      window.removeEventListener('error', handleError);
      window.removeEventListener('unhandledrejection', handleUnhandledRejection);
    };
  }, []);

  if (error) {
    return (
      <div className="error-boundary">
        <div className="error-container">
          <h1>⚠️ Erro</h1>
          <p className="error-message">{error.message}</p>
          {error.source && (
            <p className="error-details">
              Arquivo: {error.source}:{error.lineno}
            </p>
          )}
          <button 
            className="error-button"
            onClick={() => window.location.reload()}
          >
            Recarregar página
          </button>
        </div>
      </div>
    );
  }

  return children;
}

// components/Clientes/Clientes.jsx
import './index.css'
import { Search, ChevronDown, Plus } from "lucide-react";
import { useState } from "react";
import { useClientes } from '../../hooks/useClientes';
import Card_linha from '../card_linha';

const clienteVazio = { nome: "", email: "", telefone: "" };

function FormCliente({ dados, onChange }) {
  return (
    <div className="form-cliente">
      <label>Nome
        <input value={dados.nome} onChange={e => onChange({ ...dados, nome: e.target.value })} placeholder="Nome completo" />
      </label>
      <label>Email
        <input value={dados.email} onChange={e => onChange({ ...dados, email: e.target.value })} placeholder="email@exemplo.com" />
      </label>
      <label>Telefone
        <input value={dados.telefone} onChange={e => onChange({ ...dados, telefone: e.target.value })} placeholder="41 9 9999-0000" />
      </label>
    </div>
  );
}

function Clientes() {
  const [busca, setBusca]               = useState("");
  const [ordem, setOrdem]               = useState("");
  const [modalCriar, setModalCriar]     = useState(false);
  const [modalEditar, setModalEditar]   = useState(null);
  const [form, setForm]                 = useState(clienteVazio);
  const { clientes, carregando, erro, criar: adicionarCliente, editar: editarCliente, deletar: removerCliente } = useClientes();
  if (carregando) return <p>Carregando...</p>;
  if (erro) return <p>Erro: {erro}</p>;

  const clientesFiltrados = clientes
    .filter(c =>
      c.nome.toLowerCase().includes(busca.toLowerCase()) ||
      c.email.toLowerCase().includes(busca.toLowerCase())
    )
    .sort((a, b) => {
      if (ordem === "az") return a.nome.localeCompare(b.nome);
      if (ordem === "za") return b.nome.localeCompare(a.nome);
      return 0;
    });

  function handleCriar(event) {
    event.preventDefault();
    if (!form.nome.trim()) return;

    adicionarCliente({ nome: form.nome, telefone: form.telefone, email: form.email })
      .then(() => {
        setModalCriar(false);
        setForm(clienteVazio);
      })
      .catch(err => {
        console.error("Erro ao criar cliente:", err);
      });
  }

  function handleEditar(event) {
    event.preventDefault();
    if (!modalEditar) return;

    editarCliente(modalEditar.id, { nome: modalEditar.nome, telefone: modalEditar.telefone, email: modalEditar.email })
      .then(() => {
        setModalEditar(null);
      })
      .catch(err => {
        console.error("Erro ao editar cliente:", err);
      });
  }

  return (
    <section className="section-clientes">
      <div className="conteudo-95 layout">
        <div className="conteudo">

          <h1 className="titulo t1">Clientes</h1>

          <div className="filtros">
            <div className="input-container">
              <select className="input" value={ordem} onChange={e => setOrdem(e.target.value)}>
                <option value="">Ordenar</option>
                <option value="az">Alfabética (A-Z)</option>
                <option value="za">Alfabética (Z-A)</option>
              </select>
              <ChevronDown className="icon" size={18} />
            </div>
            <div className="input-container">
              <input
                type="text"
                placeholder="Buscar"
                className="input"
                value={busca}
                onChange={e => setBusca(e.target.value)}
              />
              <Search className="icon" size={18} />
            </div>
          </div>

          {/*Tabela CRUD*/}
          <div className="cards">
            {clientesFiltrados.length === 0 ? (
              <div className="clientes-vazio">Nenhum cliente encontrado.</div>
            ) : (
              clientesFiltrados.map((c) => (
                <Card_linha
                  key={c.id}
                  titulo={c.nome}
                  informacoes={{
                    Email: c.email,
                    Telefone: c.telefone,
                  }}
                  onEditar={() => setModalEditar({ ...c })}
                  onDeletar={() => removerCliente(c.id)}
                />
              ))
            )}
          </div>

        </div>
      </div>

      {/* FAB – Novo cliente */}
      <button className="clientes-fab" title="Novo cliente" onClick={() => { setForm(clienteVazio); setModalCriar(true); }}>
        <Plus size={24} />
      </button>

      {/* Modal: Criar */}
      {modalCriar && (
        <div className="modal">
          <form onSubmit={handleCriar}>
            <h2 className="modal-titulo">Novo Cliente</h2>
            <FormCliente dados={form} onChange={setForm} />
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => { setModalCriar(false); setForm(clienteVazio); }}>Cancelar</button>
              <button type="submit" className="btn-primario">Criar</button>
            </div>
          </form>
        </div>
      )}

      {/* Modal: Editar */}
      {modalEditar && (
        <div className="modal">
          <form onSubmit={handleEditar}>
            <h2 className="modal-titulo">Editar Cliente</h2>
            <FormCliente dados={modalEditar} onChange={setModalEditar} />
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => setModalEditar(null)}>Cancelar</button>
              <button type="submit" className="btn-primario">Salvar</button>
            </div>
          </form>
        </div>
      )}

    </section>
  );
}

export default Clientes;

// components/Clientes/Clientes.jsx
import './index.css'
import { Search, ChevronDown, Plus } from "lucide-react";
import { useState } from "react";
import Swal from "sweetalert2";
import { useClientes } from '../../hooks/useClientes';
import Card_linha from '../card_linha';

const clienteVazio = { nome: "", email: "", telefone: "" };

function FormCliente({ dados, onChange }) {
  return (
    <div className="form-cliente">
      <label>Nome
        <input value={dados.nome} onChange={e => onChange({ ...dados, nome: e.target.value })} placeholder="Nome completo" />
      </label>
      <label>Email
        <input value={dados.email} onChange={e => onChange({ ...dados, email: e.target.value })} placeholder="email@exemplo.com" />
      </label>
      <label>Telefone
        <input value={dados.telefone} onChange={e => onChange({ ...dados, telefone: e.target.value })} placeholder="41 9 9999-0000" />
      </label>
    </div>
  );
}

function Clientes() {
  const [busca, setBusca]               = useState("");
  const [ordem, setOrdem]               = useState("");
  const [modalCriar, setModalCriar]     = useState(false);
  const [modalEditar, setModalEditar]   = useState(null);
  const [form, setForm]                 = useState(clienteVazio);
  const { clientes, carregando, erro, criar: adicionarCliente, editar: editarCliente, deletar: removerCliente } = useClientes();
  if (carregando) return <p>Carregando...</p>;
  if (erro) return <p>Erro: {erro}</p>;

  const clientesFiltrados = clientes
    .filter(c =>
      c.nome.toLowerCase().includes(busca.toLowerCase()) ||
      c.email.toLowerCase().includes(busca.toLowerCase())
    )
    .sort((a, b) => {
      if (ordem === "az") return a.nome.localeCompare(b.nome);
      if (ordem === "za") return b.nome.localeCompare(a.nome);
      return 0;
    });

  function handleCriar(event) {
    event.preventDefault();
    // Validações obrigatórias
    if (!form.nome.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Nome é obrigatório para preenchimento" });
      return;
    }
    if (!form.email.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Email é obrigatório para preenchimento" });
      return;
    }
    if (!form.telefone.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Telefone é obrigatório para preenchimento" });
      return;
    }

    adicionarCliente({ nome: form.nome, telefone: form.telefone, email: form.email })
      .then(() => {
        setModalCriar(false);
        setForm(clienteVazio);
      })
      .catch(err => {
        console.error("Erro ao criar cliente:", err);
        // O erro é tratado no hook com Swal
      });
  }

  function handleEditar(event) {
    event.preventDefault();
    if (!modalEditar) return;

    // Validações obrigatórias para edição
    if (!modalEditar.nome.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Nome é obrigatório para preenchimento" });
      return;
    }
    if (!modalEditar.email.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Email é obrigatório para preenchimento" });
      return;
    }
    if (!modalEditar.telefone.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Telefone é obrigatório para preenchimento" });
      return;
    }

    editarCliente(modalEditar.id, { nome: modalEditar.nome, telefone: modalEditar.telefone, email: modalEditar.email })
      .then(() => {
        setModalEditar(null);
      })
      .catch(err => {
        console.error("Erro ao editar cliente:", err);
        // O erro é tratado no hook com Swal
      });
  }

  return (
    <section className="section-clientes">
      <div className="conteudo-95 layout">
        <div className="conteudo">

          <h1 className="titulo t1">Clientes</h1>

          <div className="filtros">
            <div className="input-container">
              <select className="input" value={ordem} onChange={e => setOrdem(e.target.value)}>
                <option value="">Ordenar</option>
                <option value="az">Alfabética (A-Z)</option>
                <option value="za">Alfabética (Z-A)</option>
              </select>
              <ChevronDown className="icon" size={18} />
            </div>
            <div className="input-container">
              <input
                type="text"
                placeholder="Buscar"
                className="input"
                value={busca}
                onChange={e => setBusca(e.target.value)}
              />
              <Search className="icon" size={18} />
            </div>
          </div>

          {/*Tabela CRUD*/}
          <div className="cards">
            {clientesFiltrados.length === 0 ? (
              <div className="clientes-vazio">Nenhum cliente encontrado.</div>
            ) : (
              clientesFiltrados.map((c) => (
                <Card_linha
                  key={c.id}
                  titulo={c.nome}
                  informacoes={{
                    Email: c.email,
                    Telefone: c.telefone,
                  }}
                  onEditar={() => setModalEditar({ ...c })}
                  onDeletar={() => removerCliente(c.id)}
                />
              ))
            )}
          </div>

        </div>
      </div>

      {/* FAB – Novo cliente */}
      <button className="clientes-fab" title="Novo cliente" onClick={() => { setForm(clienteVazio); setModalCriar(true); }}>
        <Plus size={24} />
      </button>

      {/* Modal: Criar */}
      {modalCriar && (
        <div className="modal">
          <form onSubmit={handleCriar}>
            <h2 className="modal-titulo">Novo Cliente</h2>
            <FormCliente dados={form} onChange={setForm} />
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => { setModalCriar(false); setForm(clienteVazio); }}>Cancelar</button>
              <button type="submit" className="btn-primario">Criar</button>
            </div>
          </form>
        </div>
      )}

      {/* Modal: Editar */}
      {modalEditar && (
        <div className="modal">
          <form onSubmit={handleEditar}>
            <h2 className="modal-titulo">Editar Cliente</h2>
            <FormCliente dados={modalEditar} onChange={setModalEditar} />
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => setModalEditar(null)}>Cancelar</button>
              <button type="submit" className="btn-primario">Salvar</button>
            </div>
          </form>
        </div>
      )}

    </section>
  );
}

export default Clientes;

import { useAdministradores } from "../../hooks/useAdministradores";
import { useAtores } from "../../hooks/useAtores";
import Card_linha from "../card_linha";
import './index.css'
import { Search, ChevronDown, Plus } from "lucide-react";
import { useState } from "react";

const adminVazio = { nome: "", email: "", telefone: "", senha: "", tipo: "ADMIN" };
const atorVazio  = { nome: "", email: "", senha: "", telefone: "", genero: "", altura: "", peso: "", observacao: "" };

function FormAdministrador({ dados, onChange }) {
  return (
    <div className="form-colaborador">
      <label className="campo-largo">Nome
        <input value={dados.nome} onChange={e => onChange({ ...dados, nome: e.target.value })} placeholder="Nome completo" />
      </label>
      <label className="campo-largo">Email
        <input value={dados.email} onChange={e => onChange({ ...dados, email: e.target.value })} placeholder="email@exemplo.com" />
      </label>
      <label>Telefone
        <input value={dados.telefone} onChange={e => onChange({ ...dados, telefone: e.target.value })} placeholder="41 9 9999-0000" />
      </label>
      <label>Senha
        <input type="password" value={dados.senha} onChange={e => onChange({ ...dados, senha: e.target.value })} placeholder="Senha" />
      </label>
    </div>
  );
}

function FormAtor({ dados, onChange }) {
  return (
    <div className="form-colaborador">
      <label className="campo-largo">Nome
        <input value={dados.nome} onChange={e => onChange({ ...dados, nome: e.target.value })} placeholder="Nome completo" />
      </label>
      <label className="campo-largo">Email
        <input value={dados.email} onChange={e => onChange({ ...dados, email: e.target.value })} placeholder="email@exemplo.com" />
      </label>
      <label>Senha
        <input type="password" value={dados.senha} onChange={e => onChange({ ...dados, senha: e.target.value })} placeholder="Senha" />
      </label>
      <label>Telefone
        <input value={dados.telefone} onChange={e => onChange({ ...dados, telefone: e.target.value })} placeholder="41 9 9999-0000" />
      </label>
      <label>Gênero
        <select value={dados.genero} onChange={e => onChange({ ...dados, genero: e.target.value })}>
          <option value="">Selecione</option>
          <option value="Masculino">Masculino</option>
          <option value="Feminino">Feminino</option>
          <option value="Outro">Outro</option>
        </select>
      </label>
      <label>Altura (m)
        <input type="number" step="0.01" value={dados.altura} onChange={e => onChange({ ...dados, altura: e.target.value })} placeholder="1.80" />
      </label>
      <label>Peso (kg)
        <input type="number" value={dados.peso} onChange={e => onChange({ ...dados, peso: e.target.value })} placeholder="78" />
      </label>
      <label className="campo-largo">Observação
        <textarea value={dados.observacao} onChange={e => onChange({ ...dados, observacao: e.target.value })} placeholder="Observações..." />
      </label>
    </div>
  );
}

function Colaboradores() {
  const { administradores, carregando: carregandoAdministradores, erro: erroAdministradores, deletar: deletarAdmin, criar: criarAdmin, editar: editarAdmin } = useAdministradores();
  const { atores, carregando: carregandoAtores, erro: erroAtores, deletar: deletarAtor, criar: criarAtor, editar: editarAtor } = useAtores();

  const [modalCriar, setModalCriar]   = useState(false);
  const [modalEditar, setModalEditar] = useState(null); 
  const [tipoForm, setTipoForm]       = useState("admin");
  const [formAdmin, setFormAdmin]     = useState(adminVazio);
  const [formAtor, setFormAtor]       = useState(atorVazio);

  if (carregandoAdministradores || carregandoAtores) return <p>Carregando...</p>;
  if (erroAdministradores || erroAtores) return <p>Erro: {erroAdministradores || erroAtores}</p>;

  function handleCriar(event) {
    event.preventDefault();
    if (tipoForm === "admin") {
      criarAdmin(formAdmin)
        .then(() => { setModalCriar(false); setFormAdmin(adminVazio); });
    } else {
      criarAtor({ ...formAtor, altura: parseFloat(formAtor.altura), peso: parseFloat(formAtor.peso), ativo: true })
        .then(() => { setModalCriar(false); setFormAtor(atorVazio); });
    }
  }

  function handleEditar(event) {
    event.preventDefault();
    if (!modalEditar) return;

    if (modalEditar.tipo === "admin") {
      editarAdmin(modalEditar.dados.id, modalEditar.dados)
        .then(() => setModalEditar(null));
    } else {
      editarAtor(modalEditar.dados.id, {
        ...modalEditar.dados,
        altura: parseFloat(modalEditar.dados.altura),
        peso: parseFloat(modalEditar.dados.peso),
      }).then(() => setModalEditar(null));
    }
  }

  return (
    <section className="section-colaboradores">
      <div className="conteudo-95 layout">
        <div className="conteudo">
          <h1 className="titulo t1">Colaboradores</h1>
          <div className="filtros">
            <div className="input-container">
              <select className="input">
                <option value="">Ordenar</option>
                <option value="">Alfabética(A-Z)</option>
                <option value="">Alfabética(Z-A)</option>
                <option value="">Disponibilidade</option>
              </select>
              <ChevronDown className="icon" size={18} />
            </div>
            <div className="input-container">
              <input type="text" placeholder="Buscar" className="input" />
              <Search className="icon" size={18} />
            </div>
          </div>

          <div className="lista lista-administradores">
            <div className="titulo t2"><p>Administradores</p></div>
            <div className="cards">
              {administradores.map((admin) => (
                <Card_linha
                  key={admin.id}
                  titulo={admin.nome}
                  informacoes={{ Email: admin.email, Celular: admin.telefone }}
                  onEditar={() => setModalEditar({ tipo: "admin", dados: { ...admin, senha: "" } })}
                  onDeletar={() => deletarAdmin(admin.id)}
                />
              ))}
            </div>
          </div>

          <div className="lista lista-atores">
            <div className="titulo t2"><p>Atores</p></div>
            <div className="cards">
              {atores.map((ator) => (
                <Card_linha
                  key={ator.id}
                  titulo={ator.nome}
                  informacoes={{ Email: ator.email, Celular: ator.telefone, Gênero: ator.genero, Altura: ator.altura, Peso: ator.peso, Observação: ator.observacao }}
                  onEditar={() => setModalEditar({ tipo: "ator", dados: { ...ator, senha: "" } })}
                  onDeletar={() => deletarAtor(ator.id)}
                />
              ))}
            </div>
          </div>
        </div>
      </div>

      <button className="btn-create" onClick={() => setModalCriar(true)}>
        <Plus size={24} />
      </button>

      {modalCriar && (
        <div className="modal">
          <form onSubmit={handleCriar}>
            <h2 className="modal-titulo">Novo Colaborador</h2>
            <div className="modal-abas">
              <button type="button" className={tipoForm === "admin" ? "aba-ativa" : ""} onClick={() => setTipoForm("admin")}>Administrador</button>
              <button type="button" className={tipoForm === "ator"  ? "aba-ativa" : ""} onClick={() => setTipoForm("ator")}>Ator</button>
            </div>
            {tipoForm === "admin"
              ? <FormAdministrador dados={formAdmin} onChange={setFormAdmin} />
              : <FormAtor dados={formAtor} onChange={setFormAtor} />
            }
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => { setModalCriar(false); setFormAdmin(adminVazio); setFormAtor(atorVazio); }}>Cancelar</button>
              <button type="submit" className="btn-primario">Criar</button>
            </div>
          </form>
        </div>
      )}

      {modalEditar && (
        <div className="modal">
          <form onSubmit={handleEditar}>
            <h2 className="modal-titulo">
              Editar {modalEditar.tipo === "admin" ? "Administrador" : "Ator"}
            </h2>
            {modalEditar.tipo === "admin"
              ? <FormAdministrador dados={modalEditar.dados} onChange={dados => setModalEditar({ ...modalEditar, dados })} />
              : <FormAtor dados={modalEditar.dados} onChange={dados => setModalEditar({ ...modalEditar, dados })} />
            }
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => setModalEditar(null)}>Cancelar</button>
              <button type="submit" className="btn-primario">Salvar</button>
            </div>
          </form>
        </div>
      )}
    </section>
  );
}

export default Colaboradores;

import { useAdministradores } from "../../hooks/useAdministradores";
import { useAtores } from "../../hooks/useAtores";
import Card_linha from "../card_linha";
import './index.css'
import { Search, ChevronDown, Plus } from "lucide-react";
import Swal from "sweetalert2";
import { useState } from "react";

const adminVazio = { nome: "", email: "", telefone: "", senha: "", tipo: "ADMIN" };
const atorVazio  = { nome: "", email: "", senha: "", telefone: "", genero: "", altura: "", peso: "", observacao: "" };

function FormAdministrador({ dados, onChange }) {
  return (
    <div className="form-colaborador">
      <label className="campo-largo">Nome
        <input value={dados.nome} onChange={e => onChange({ ...dados, nome: e.target.value })} placeholder="Nome completo" />
      </label>
      <label className="campo-largo">Email
        <input value={dados.email} onChange={e => onChange({ ...dados, email: e.target.value })} placeholder="email@exemplo.com" />
      </label>
      <label>Telefone
        <input value={dados.telefone} onChange={e => onChange({ ...dados, telefone: e.target.value })} placeholder="41 9 9999-0000" />
      </label>
      <label>Senha
        <input type="password" value={dados.senha} onChange={e => onChange({ ...dados, senha: e.target.value })} placeholder="Senha" />
      </label>
    </div>
  );
}

function FormAtor({ dados, onChange }) {
  return (
    <div className="form-colaborador">
      <label className="campo-largo">Nome
        <input value={dados.nome} onChange={e => onChange({ ...dados, nome: e.target.value })} placeholder="Nome completo" />
      </label>
      <label className="campo-largo">Email
        <input value={dados.email} onChange={e => onChange({ ...dados, email: e.target.value })} placeholder="email@exemplo.com" />
      </label>
      <label>Senha
        <input type="password" value={dados.senha} onChange={e => onChange({ ...dados, senha: e.target.value })} placeholder="Senha" />
      </label>
      <label>Telefone
        <input value={dados.telefone} onChange={e => onChange({ ...dados, telefone: e.target.value })} placeholder="41 9 9999-0000" />
      </label>
      <label>Gênero
        <select value={dados.genero} onChange={e => onChange({ ...dados, genero: e.target.value })}>
          <option value="">Selecione</option>
          <option value="Masculino">Masculino</option>
          <option value="Feminino">Feminino</option>
          <option value="Outro">Outro</option>
        </select>
      </label>
      <label>Altura (m)
        <input type="number" step="0.01" value={dados.altura} onChange={e => onChange({ ...dados, altura: e.target.value })} placeholder="1.80" />
      </label>
      <label>Peso (kg)
        <input type="number" value={dados.peso} onChange={e => onChange({ ...dados, peso: e.target.value })} placeholder="78" />
      </label>
      <label className="campo-largo">Observação
        <textarea value={dados.observacao} onChange={e => onChange({ ...dados, observacao: e.target.value })} placeholder="Observações..." />
      </label>
    </div>
  );
}

function Colaboradores() {
  const { administradores, carregando: carregandoAdministradores, erro: erroAdministradores, deletar: deletarAdmin, criar: criarAdmin, editar: editarAdmin } = useAdministradores();
  const { atores, carregando: carregandoAtores, erro: erroAtores, deletar: deletarAtor, criar: criarAtor, editar: editarAtor } = useAtores();

  const [modalCriar, setModalCriar]   = useState(false);
  const [modalEditar, setModalEditar] = useState(null); 
  const [tipoForm, setTipoForm]       = useState("admin");
  const [formAdmin, setFormAdmin]     = useState(adminVazio);
  const [formAtor, setFormAtor]       = useState(atorVazio);

  if (carregandoAdministradores || carregandoAtores) return <p>Carregando...</p>;
  if (erroAdministradores || erroAtores) return <p>Erro: {erroAdministradores || erroAtores}</p>;

  function handleCriar(event) {
    event.preventDefault();
    if (tipoForm === "admin") {
      if (!formAdmin.nome.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Nome é obrigatório para preenchimento" });
        return;
      }
      if (!formAdmin.email.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Email é obrigatório para preenchimento" });
        return;
      }
      if (!formAdmin.telefone.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Telefone é obrigatório para preenchimento" });
        return;
      }
      if (!formAdmin.senha.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Senha é obrigatório para preenchimento" });
        return;
      }
      if (!formAdmin.tipo?.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Tipo é obrigatório para preenchimento" });
        return;
      }

      criarAdmin(formAdmin)
        .then(() => {
          setModalCriar(false);
          setFormAdmin(adminVazio);
        })
        .catch(err => {
          console.error("Erro ao criar administrador:", err);
          // O erro é tratado no hook com Swal
        });
    } else {
      // Ator
      if (!formAtor.nome.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Nome é obrigatório para preenchimento" });
        return;
      }
      if (!formAtor.email.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Email é obrigatório para preenchimento" });
        return;
      }
      if (!formAtor.telefone.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Telefone é obrigatório para preenchimento" });
        return;
      }
      if (!formAtor.senha.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Senha é obrigatório para preenchimento" });
        return;
      }
      if (!formAtor.genero.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Gênero é obrigatório para preenchimento" });
        return;
      }
      if (formAtor.altura === "" || formAtor.altura === null || formAtor.altura === undefined || isNaN(Number(formAtor.altura))) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Altura é obrigatório para preenchimento e deve ser um número" });
        return;
      }
      if (formAtor.peso === "" || formAtor.peso === null || formAtor.peso === undefined || isNaN(Number(formAtor.peso))) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Peso é obrigatório para preenchimento e deve ser um número" });
        return;
      }

      criarAtor({
        ...formAtor,
        altura: parseFloat(formAtor.altura),
        peso: parseFloat(formAtor.peso),
        ativo: true
      })
        .then(() => {
          setModalCriar(false);
          setFormAtor(atorVazio);
        })
        .catch(err => {
          console.error("Erro ao criar ator:", err);
          // O erro é tratado no hook com Swal
        });
    }
  }

  function handleEditar(event) {
    event.preventDefault();
    if (!modalEditar) return;

    // validações para edição (admin ou ator)
    const dados = modalEditar.dados || {};
    if (!dados.nome?.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Nome é obrigatório para preenchimento" });
      return;
    }
    if (!dados.email?.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Email é obrigatório para preenchimento" });
      return;
    }
    if (!dados.telefone?.trim()) {
      Swal.fire({ icon: "warning", title: "Validação", text: "O campo Telefone é obrigatório para preenchimento" });
      return;
    }

    if (modalEditar.tipo === "admin") {
      if (!dados.senha?.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Senha é obrigatório para preenchimento" });
        return;
      }
      if (!dados.tipo?.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Tipo é obrigatório para preenchimento" });
        return;
      }

      editarAdmin(modalEditar.dados.id, modalEditar.dados)
        .then(() => {
          setModalEditar(null);
        })
        .catch(err => {
          console.error("Erro ao editar administrador:", err);
          // O erro é tratado no hook com Swal
        });
    } else {
      // ator
      if (!dados.senha?.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Senha é obrigatório para preenchimento" });
        return;
      }
      if (!dados.genero?.trim()) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Gênero é obrigatório para preenchimento" });
        return;
      }
      if (dados.altura === "" || dados.altura === null || dados.altura === undefined || isNaN(Number(dados.altura))) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Altura é obrigatório para preenchimento e deve ser um número" });
        return;
      }
      if (dados.peso === "" || dados.peso === null || dados.peso === undefined || isNaN(Number(dados.peso))) {
        Swal.fire({ icon: "warning", title: "Validação", text: "O campo Peso é obrigatório para preenchimento e deve ser um número" });
        return;
      }

      editarAtor(modalEditar.dados.id, {
        ...modalEditar.dados,
        altura: parseFloat(modalEditar.dados.altura),
        peso: parseFloat(modalEditar.dados.peso),
      })
        .then(() => {
          setModalEditar(null);
        })
        .catch(err => {
          console.error("Erro ao editar ator:", err);
          // O erro é tratado no hook com Swal
        });
    }
  }

  return (
    <section className="section-colaboradores">
      <div className="conteudo-95 layout">
        <div className="conteudo">
          <h1 className="titulo t1">Colaboradores</h1>
          <div className="filtros">
            <div className="input-container">
              <select className="input">
                <option value="">Ordenar</option>
                <option value="">Alfabética(A-Z)</option>
                <option value="">Alfabética(Z-A)</option>
                <option value="">Disponibilidade</option>
              </select>
              <ChevronDown className="icon" size={18} />
            </div>
            <div className="input-container">
              <input type="text" placeholder="Buscar" className="input" />
              <Search className="icon" size={18} />
            </div>
          </div>

          <div className="lista lista-administradores">
            <div className="titulo t2"><p>Administradores</p></div>
            <div className="cards">
              {administradores.map((admin) => (
                <Card_linha
                  key={admin.id}
                  titulo={admin.nome}
                  informacoes={{ Email: admin.email, Celular: admin.telefone }}
                  onEditar={() => setModalEditar({ tipo: "admin", dados: { ...admin, senha: "" } })}
                  onDeletar={() => deletarAdmin(admin.id)}
                />
              ))}
            </div>
          </div>

          <div className="lista lista-atores">
            <div className="titulo t2"><p>Atores</p></div>
            <div className="cards">
              {atores.map((ator) => (
                <Card_linha
                  key={ator.id}
                  titulo={ator.nome}
                  informacoes={{ Email: ator.email, Celular: ator.telefone, Gênero: ator.genero, Altura: ator.altura, Peso: ator.peso, Observação: ator.observacao }}
                  onEditar={() => setModalEditar({ tipo: "ator", dados: { ...ator, senha: "" } })}
                  onDeletar={() => deletarAtor(ator.id)}
                />
              ))}
            </div>
          </div>
        </div>
      </div>

      <button className="btn-create" onClick={() => setModalCriar(true)}>
        <Plus size={24} />
      </button>

      {modalCriar && (
        <div className="modal">
          <form onSubmit={handleCriar}>
            <h2 className="modal-titulo">Novo Colaborador</h2>
            <div className="modal-abas">
              <button type="button" className={tipoForm === "admin" ? "aba-ativa" : ""} onClick={() => setTipoForm("admin")}>Administrador</button>
              <button type="button" className={tipoForm === "ator"  ? "aba-ativa" : ""} onClick={() => setTipoForm("ator")}>Ator</button>
            </div>
            {tipoForm === "admin"
              ? <FormAdministrador dados={formAdmin} onChange={setFormAdmin} />
              : <FormAtor dados={formAtor} onChange={setFormAtor} />
            }
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => { setModalCriar(false); setFormAdmin(adminVazio); setFormAtor(atorVazio); }}>Cancelar</button>
              <button type="submit" className="btn-primario">Criar</button>
            </div>
          </form>
        </div>
      )}

      {modalEditar && (
        <div className="modal">
          <form onSubmit={handleEditar}>
            <h2 className="modal-titulo">
              Editar {modalEditar.tipo === "admin" ? "Administrador" : "Ator"}
            </h2>
            {modalEditar.tipo === "admin"
              ? <FormAdministrador dados={modalEditar.dados} onChange={dados => setModalEditar({ ...modalEditar, dados })} />
              : <FormAtor dados={modalEditar.dados} onChange={dados => setModalEditar({ ...modalEditar, dados })} />
            }
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => setModalEditar(null)}>Cancelar</button>
              <button type="submit" className="btn-primario">Salvar</button>
            </div>
          </form>
        </div>
      )}
    </section>
  );
}

export default Colaboradores;

// components/Personagens.jsx
import { usePersonagens } from "../../hooks/usePersonagem";
import './index.css'
import { Search, ChevronDown, Plus, Pencil, Trash2 } from "lucide-react";
import logo from '../../assets/logo.png'
import { useState } from "react";

const personagemVazio = {
  nome: "",
  descricao: "",
  foto: "",
};

function FormPersonagem({ dados, onChange }) {
  return (
    <div className="form-personagem">
      <label>Nome
        <input value={dados.nome} onChange={e => onChange({ ...dados, nome: e.target.value })} placeholder="Nome do personagem" />
      </label>
      <label>Descrição
        <textarea value={dados.descricao} onChange={e => onChange({ ...dados, descricao: e.target.value })} placeholder="Descrição do personagem" rows={3} />
      </label>
      <label>Foto (URL)
        <input value={dados.foto} onChange={e => onChange({ ...dados, foto: e.target.value })} placeholder="URL da foto" />
      </label>
    </div>
  );
}

function Personagens() {
  const [busca, setBusca] = useState("");
  const [ordem, setOrdem] = useState("");
  const [modalCriar, setModalCriar] = useState(false);
  const [modalEditar, setModalEditar] = useState(null);
  const [form, setForm] = useState(personagemVazio);
  const [imagem] = useState(logo);

  const { personagens, carregando, erro, criar, editar, deletar } = usePersonagens();

  if (carregando) return <p>Carregando...</p>;
  if (erro) return <p>Erro: {erro}</p>;

  const personagensFiltrados = personagens
    .filter(p =>
      p.nome.toLowerCase().includes(busca.toLowerCase()) ||
      p.descricao?.toLowerCase().includes(busca.toLowerCase())
    )
    .sort((a, b) => {
      if (ordem === "az") return a.nome.localeCompare(b.nome);
      if (ordem === "za") return b.nome.localeCompare(a.nome);
      return 0;
    });

  function handleCriar(event) {
    event.preventDefault();
    if (!form.nome.trim()) return;

    criar(form).then(() => {
      setModalCriar(false);
      setForm(personagemVazio);
    });
  }

  function handleEditar(event) {
    event.preventDefault();
    if (!modalEditar) return;

    editar(modalEditar.id, {
      nome: modalEditar.nome,
      descricao: modalEditar.descricao,
      foto: modalEditar.foto,
    }).then(() => setModalEditar(null));
  }

  return (
    <section className="section-personagens">
      <div className="conteudo-95 layout">
        <div className="conteudo">

          <h1 className="titulo t1">Personagens</h1>
          <div className="filtros">
            <div className="input-container">
              <select className="input" value={ordem} onChange={e => setOrdem(e.target.value)}>
                <option value="">Ordenar</option>
                <option value="az">Alfabética (A-Z)</option>
                <option value="za">Alfabética (Z-A)</option>
              </select>
              <ChevronDown className="icon" size={18} />
            </div>
            <div className="input-container">
              <input
                type="text"
                placeholder="Buscar"
                className="input"
                value={busca}
                onChange={e => setBusca(e.target.value)}
              />
              <Search className="icon" size={18} />
            </div>
          </div>
          <ul className="lista-personagem">
            {personagensFiltrados.map(personagem => (
              <li key={personagem.id} className="card-personagem">
                <div className="imagem-container">
                  <img src={personagem.foto || imagem} alt="" className="imagem" />
                  <div className="card-personagem-acoes">
                    <button
                      className="btn-icone btn-editar"
                      type="button"
                      title="Editar"
                      onClick={() => setModalEditar({ ...personagem })}
                    >
                      <Pencil size={16} />
                    </button>
                    <button
                      className="btn-icone btn-deletar"
                      type="button"
                      title="Deletar"
                      onClick={() => deletar(personagem.id)}
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
                <div className="textos">
                  <div className="texto t1"><p>{personagem.nome}</p></div>
                  <div className="texto t2"><p>{personagem.descricao || "Sem descrição"}</p></div>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* FAB – Novo personagem */}
      <button className="personagens-fab" title="Novo personagem" onClick={() => { setForm(personagemVazio); setModalCriar(true); }}>
        <Plus size={24} />
      </button>

      {/* Modal: Criar */}
      {modalCriar && (
        <div className="modal">
          <form onSubmit={handleCriar}>
            <h2 className="modal-titulo">Novo Personagem</h2>
            <FormPersonagem dados={form} onChange={setForm} />
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => { setModalCriar(false); setForm(personagemVazio); }}>Cancelar</button>
              <button type="submit" className="btn-primario">Criar</button>
            </div>
          </form>
        </div>
      )}

      {/* Modal: Editar */}
      {modalEditar && (
        <div className="modal">
          <form onSubmit={handleEditar}>
            <h2 className="modal-titulo">Editar Personagem</h2>
            <FormPersonagem dados={modalEditar} onChange={setModalEditar} />
            <div className="modal-acoes">
              <button type="button" className="btn-secundario" onClick={() => setModalEditar(null)}>Cancelar</button>
              <button type="submit" className="btn-primario">Salvar</button>
            </div>
          </form>
        </div>
      )}

    </section>
  );
}

export default Personagens;

